'use strict';

const fs = require('node:fs');
const fsp = require('node:fs/promises');
const path = require('node:path');
const crypto = require('node:crypto');
const multer = require('multer');

const DIRS = { video: 'videos', image: 'images', tmp: 'tmp' };

// Stored file names are always generated by us: 32 hex chars + a known extension.
const STORED_NAME = /^[a-f0-9]{32}\.(mp4|webm|mov|jpg|png|webp|gif)$/;

const CONTENT_TYPES = {
  mp4: 'video/mp4', webm: 'video/webm', mov: 'video/quicktime',
  jpg: 'image/jpeg', png: 'image/png', webp: 'image/webp', gif: 'image/gif',
};

class MediaError extends Error {
  constructor(message, status = 400) {
    super(message);
    this.status = status;
    this.expose = true;
  }
}

function ensureDirs(uploadDir) {
  for (const d of Object.values(DIRS)) fs.mkdirSync(path.join(uploadDir, d), { recursive: true });
}

const VIDEO_BRANDS = new Set(['isom', 'iso2', 'iso3', 'iso4', 'iso5', 'iso6', 'mp41', 'mp42', 'avc1', 'M4V ', 'M4VP', 'dash', 'mmp4', 'MSNV', 'NDAS', 'f4v ', 'XAVC']);

/** Detect the real file type from its first bytes. Client supplied names and MIME types are ignored. */
function sniff(buf) {
  if (buf.length >= 12) {
    // ISO base media (MP4 / MOV): "ftyp" box at offset 4.
    if (buf.toString('latin1', 4, 8) === 'ftyp') {
      const brand = buf.toString('latin1', 8, 12);
      if (brand === 'qt  ') return { kind: 'video', ext: 'mov' };
      if (VIDEO_BRANDS.has(brand)) return { kind: 'video', ext: 'mp4' };
      return null; // HEIC/AVIF images, M4A audio and other ISO-BMFF files are rejected.
    }
    if (buf[0] === 0x1a && buf[1] === 0x45 && buf[2] === 0xdf && buf[3] === 0xa3) return { kind: 'video', ext: 'webm' };
    if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return { kind: 'image', ext: 'jpg' };
    if (buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return { kind: 'image', ext: 'png' };
    if (buf.toString('latin1', 0, 4) === 'RIFF' && buf.toString('latin1', 8, 12) === 'WEBP') return { kind: 'image', ext: 'webp' };
    if (['GIF87a', 'GIF89a'].includes(buf.toString('latin1', 0, 6))) return { kind: 'image', ext: 'gif' };
  }
  return null;
}

async function readHead(file, bytes = 32) {
  const fh = await fsp.open(file, 'r');
  try {
    const buf = Buffer.alloc(bytes);
    const { bytesRead } = await fh.read(buf, 0, bytes, 0);
    return buf.subarray(0, bytesRead);
  } finally {
    await fh.close();
  }
}

function createUploader(config) {
  ensureDirs(config.uploadDir);
  const storage = multer.diskStorage({
    destination: path.join(config.uploadDir, DIRS.tmp),
    filename: (_req, _file, cb) => cb(null, `${crypto.randomBytes(16).toString('hex')}.upload`),
  });
  const allowedFields = new Set(['video', 'thumbnail', 'avatar']);
  return multer({
    storage,
    limits: {
      fileSize: config.maxVideoBytes,
      files: 2,
      fields: 30,
      fieldSize: 16 * 1024,
      parts: 40,
      headerPairs: 50,
    },
    fileFilter: (_req, file, cb) => {
      if (!allowedFields.has(file.fieldname)) return cb(new MediaError('Unexpected file field.'));
      cb(null, true);
    },
  });
}

/**
 * Validates an uploaded temp file and moves it into permanent storage.
 * Returns the generated stored file name.
 */
async function commitUpload(config, file, expectedKind) {
  try {
    const head = await readHead(file.path);
    const type = sniff(head);
    if (!type || type.kind !== expectedKind) {
      throw new MediaError(expectedKind === 'video'
        ? 'Unsupported video file. Upload MP4, MOV or WebM.'
        : 'Unsupported image file. Upload JPG, PNG, WebP or GIF.');
    }
    if (expectedKind === 'image' && file.size > config.maxImageBytes) {
      throw new MediaError(`Images must be smaller than ${Math.round(config.maxImageBytes / 1024 / 1024)} MB.`);
    }
    const name = `${crypto.randomBytes(16).toString('hex')}.${type.ext}`;
    const dir = expectedKind === 'video' ? DIRS.video : DIRS.image;
    await fsp.rename(file.path, path.join(config.uploadDir, dir, name));
    return name;
  } catch (err) {
    await fsp.rm(file.path, { force: true });
    throw err;
  }
}

async function discardUploads(files) {
  if (!files) return;
  const list = Array.isArray(files) ? files : Object.values(files).flat();
  await Promise.all(list.map((f) => fsp.rm(f.path, { force: true }).catch(() => {})));
}

async function removeStored(config, kind, name) {
  if (!name || !STORED_NAME.test(name)) return;
  const dir = kind === 'video' ? DIRS.video : DIRS.image;
  await fsp.rm(path.join(config.uploadDir, dir, name), { force: true }).catch(() => {});
}

function publicPath(kind, name) {
  if (!name || !STORED_NAME.test(name)) return null;
  return `/media/${kind === 'video' ? DIRS.video : DIRS.image}/${name}`;
}

/**
 * Best-effort download of a thumbnail from a fixed oEmbed endpoint (TikTok / Vimeo).
 * Only our own endpoint URLs are requested, the returned image host must be on an allow-list,
 * redirects are refused, the size is capped and the bytes are sniffed before saving.
 */
const OEMBED = {
  tiktok: (id, link) => `https://www.tiktok.com/oembed?url=${encodeURIComponent(link && link.includes('/video/') ? link : `https://www.tiktok.com/@tiktok/video/${id}`)}`,
  vimeo: (id) => `https://vimeo.com/api/oembed.json?url=${encodeURIComponent(`https://vimeo.com/${id.split(':')[0]}`)}&width=1280`,
};
const THUMB_HOSTS = ['tiktokcdn.com', 'tiktokcdn-us.com', 'tiktokcdn-eu.com', 'ibyteimg.com', 'vimeocdn.com'];

async function fetchLimited(url, maxBytes, timeoutMs) {
  const res = await fetch(url, { redirect: 'error', signal: AbortSignal.timeout(timeoutMs), headers: { 'user-agent': 'PortfolioBot/1.0' } });
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const declared = Number(res.headers.get('content-length') || 0);
  if (declared > maxBytes) throw new Error('Response too large');
  const chunks = [];
  let total = 0;
  for await (const chunk of res.body) {
    total += chunk.length;
    if (total > maxBytes) throw new Error('Response too large');
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

async function fetchRemoteThumbnail(config, platform, sourceId, sourceUrl) {
  if (!config.fetchRemoteThumbnails || !OEMBED[platform]) return null;
  try {
    const meta = JSON.parse((await fetchLimited(OEMBED[platform](sourceId, sourceUrl), 256 * 1024, 6000)).toString('utf8'));
    const thumb = new URL(String(meta.thumbnail_url || ''));
    const host = thumb.hostname.toLowerCase();
    if (thumb.protocol !== 'https:' || !THUMB_HOSTS.some((h) => host === h || host.endsWith(`.${h}`))) return null;
    const buf = await fetchLimited(thumb.href, config.maxImageBytes, 8000);
    const type = sniff(buf);
    if (!type || type.kind !== 'image') return null;
    const name = `${crypto.randomBytes(16).toString('hex')}.${type.ext}`;
    await fsp.writeFile(path.join(config.uploadDir, DIRS.image, name), buf, { flag: 'wx' });
    return name;
  } catch {
    return null;
  }
}

/** Removes stale temp uploads left behind by interrupted requests. */
async function cleanTmp(config, maxAgeMs = 6 * 60 * 60 * 1000) {
  const dir = path.join(config.uploadDir, DIRS.tmp);
  const entries = await fsp.readdir(dir).catch(() => []);
  const now = Date.now();
  await Promise.all(entries.map(async (name) => {
    const p = path.join(dir, name);
    const st = await fsp.stat(p).catch(() => null);
    if (st && now - st.mtimeMs > maxAgeMs) await fsp.rm(p, { force: true }).catch(() => {});
  }));
}

module.exports = {
  createUploader,
  commitUpload,
  discardUploads,
  removeStored,
  publicPath,
  fetchRemoteThumbnail,
  cleanTmp,
  sniff,
  MediaError,
  CONTENT_TYPES,
  STORED_NAME,
  DIRS,
};
